select case when year(event_time) < 2024 then 'before_2024' when year(event_time) = 2024 then '2024' else 'after_2024' end as event_cohort, count(duration_sec) as duration_sec_count, round((100 * sum(case when page = '/cart' then 1 else 0 end)) / count(*), 1) as pct_cart from web_events where to_date(event_time) < '2024-07-01' and event_time >= '2023-10-01' group by event_cohort having duration_sec_count >= 2 order by pct_cart desc
